/* 300 original modern, child-friendly encouragements; no celebrity attribution or runtime model calls. */
(function(root,factory){const api=factory(root);if(typeof module==='object'&&module.exports)module.exports=api;else root.MathDailyQuotes=api;})(typeof window==='object'?window:globalThis,function(root){
  'use strict';
  const quotes=Object.freeze([{"id":"m009","text":"做一点，再看一看，办法会慢慢清楚。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m031","text":"错题不是失败记录，是下一次学习的路标。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m041","text":"订正不是抄答案，是重新走通思路。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m049","text":"敢说没听懂，才能给理解再一次机会。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m074","text":"走到一半觉得难，可以停一停再继续。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m088","text":"用简单的例子，试出复杂问题的规律。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m094","text":"别人做得好，不会减少你的可能。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m119","text":"选择一种方法，就认真走一遍看看。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m123","text":"隔一天还能讲清楚，才更接近真正掌握。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m139","text":"看到新知识，试着和生活里的事联系起来。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m160","text":"会表达，也包括会说“请再讲一次”。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m166","text":"不会就承认不会，才有机会真正学会。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m181","text":"一次专心做一件事，思路更容易连起来。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m197","text":"睡好觉的大脑，更容易迎接新问题。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m211","text":"数学不只在练习册里，也藏在日常生活中。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m229","text":"一句真诚的鼓励，可能帮人多试一次。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m250","text":"发现更简单的做法，也是一种创造。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m257","text":"遇到挑战时，先找一个自己能控制的步骤。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m275","text":"喜欢的事可以深入，不擅长的事可以慢慢练。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m286","text":"学会一件新事，值得给自己一个微笑。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m006","text":"大目标可以很远，第一步就在脚下。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m029","text":"把自己的推理讲清楚，让每一步都有理由。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m042","text":"这次没有做对，也能带走一个新发现。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m054","text":"听懂答案以后，试着用自己的话再说一次。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m069","text":"把目标分小，耐心就更容易跟上。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m079","text":"整理好条件，常常能省下不少弯路。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m101","text":"今天的困难，不是对你能力的最终评价。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m112","text":"先说说你的思路，再听听别人的办法。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m132","text":"会做以后再讲给别人听，思路会更清楚。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m141","text":"好奇的时候，多查一条可靠的信息。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m152","text":"认真听完别人的方法，再说你的想法。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m175","text":"为自己的选择负责，也允许自己重新选择。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m187","text":"写下接下来要做的三件事，心里会更清楚。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m210","text":"留一点空闲，让想象力自由走走。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m212","text":"买东西时算一算，就是一次真实的数学练习。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m233","text":"看见别人努力的地方，比只评价结果更有温度。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m245","text":"同一道题，可以邀请不同的思路来做客。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m269","text":"先做好准备，再给自己一个尝试的机会。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m279","text":"你可以改变主意，也可以重新制定计划。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m299","text":"把好奇留给世界，把鼓励也留给自己。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m010","text":"开始时慢一点，也是在向前走。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m027","text":"思考需要时间，安静想一会儿也很好。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m032","text":"发现一个错误，就多了一个进步的机会。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m048","text":"把“我不会”换成“我卡在这一步”。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m066","text":"今天比昨天多懂一点，就已经很好。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m090","text":"省下的时间，也可以留给休息和好奇心。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m096","text":"你的想法值得说出来，也值得被认真听见。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m110","text":"听取建议之后，试着作出自己的判断。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m134","text":"复习一点点，让学过的本领继续陪着你。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m149","text":"知道得越多，也会发现还有更多值得学习。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m164","text":"把成果分享给大家，也把功劳留给伙伴。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m179","text":"对自己说实话，是改变的第一步。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m186","text":"把手机放远一点，给眼前的任务多一点空间。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m196","text":"休息不是浪费时间，是让自己恢复力量。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m224","text":"读懂一道应用题，也是在练习理解世界。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m226","text":"对别人友善，也别忘了善待自己。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m244","text":"有趣的发现，有时来自一次意外的尝试。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m263","text":"不必一下子跨过去，可以一步一步靠近。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m281","text":"认识自己的长处，可以更好地帮助别人。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m288","text":"认真走过的每一步，都可以成为经验。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m012","text":"给一个好想法，配上一个小行动。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m022","text":"先看条件，再看问题，最后找联系。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m036","text":"把错误说清楚，就已经开始解决它。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m058","text":"想确认一下，也是一种认真的态度。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m071","text":"做得慢也没关系，把每一步想清楚。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m084","text":"当旧办法走不通，可以换一条路。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m104","text":"做自己的支持者，遇到难处先说一句“再看看”。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m109","text":"不会马上做出来，也可以先写出已知信息。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m130","text":"把今天的发现记一行，给未来的自己留个提醒。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m138","text":"带着问题阅读，收获会更具体。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m157","text":"帮助别人理解，也会加深自己的理解。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m169","text":"做错事之后，解释原因也要承担责任。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m193","text":"让今天的计划有余地，不必排满每一分钟。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m206","text":"不用每时每刻都表现优秀，也可以被喜欢。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m214","text":"单位写完整，数字才表达得明白。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m228","text":"每个人的起点不同，尊重不同的学习速度。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m242","text":"想象可以大胆，验证需要认真。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m262","text":"挑战之后回头看，经验也是一种收获。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m283","text":"为自己设目标时，既要有挑战，也要有余地。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m298","text":"明天还有新发现，今天的努力已经有意义。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m005","text":"今天愿意动手，就是进步的开始。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m030","text":"当答案出乎意料，先检查思路再下结论。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m024","text":"比较两种方法，常常比背一种更有收获。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m060","text":"勇敢举手，让问题有机会被解决。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m065","text":"坚持不是硬撑，累了可以休息后再来。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m089","text":"找准原因再练习，比盲目重复更有帮助。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m099","text":"勇敢尝试，本来就值得肯定。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m113","text":"能独立检查一步，就多掌握了一点主动权。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m133","text":"不只问“做过没有”，也问“现在还会不会”。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m137","text":"一本书可以带你认识从未见过的世界。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m153","text":"合作不是等别人做，是一起把事情做好。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m168","text":"答应的事情，记下来并努力做到。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m195","text":"学会停下来检查，也是专注的一部分。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m207","text":"照顾自己的感受，和完成任务一样需要学习。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m218","text":"找规律时，多看几个例子再作判断。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m231","text":"帮助别人之前，先听听他需要什么。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m255","text":"好点子经过尝试和修改，会变得更有用。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m264","text":"给自己设一个小挑战，看看能学到什么。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m285","text":"你正在成长，不需要现在就确定所有答案。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m294","text":"成长不总是热闹，也可以是安静地想明白。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m014","text":"先试一种方法，再决定下一步。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m018","text":"把复杂的问题拆开，先看懂其中一部分。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m038","text":"别急着擦掉错的步骤，它可能藏着重要线索。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m046","text":"不懂就问，是认真学习的表现。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m063","text":"暂时看不到变化，不等于努力没有作用。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m085","text":"记住一个公式，也要知道什么时候能用。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m091","text":"你可以暂时不会，也可以慢慢学会。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m111","text":"独立不是拒绝帮助，是愿意动脑和负责。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m131","text":"练习要有间隔，理解才有时间扎根。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m136","text":"读不懂的一句话，可以慢慢读第二遍。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m163","text":"好伙伴可以互相提醒，也可以互相鼓励。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m170","text":"自己的练习，应该留下自己的思考。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m184","text":"分心以后发现了，就轻轻把注意力带回来。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m202","text":"心情不好时，可以找信任的人说一说。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m220","text":"先理解每个数代表什么，再决定怎样计算。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m236","text":"给别人一点耐心，也给自己一点耐心。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m254","text":"想象力有很多方向，不必和别人画得一样。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m266","text":"面对陌生任务，先观察再动手。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m282","text":"遇到挫折时，区分“这次没做好”和“我不好”。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m290","text":"把今天的收获说出来，让自己听见成长。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m001","text":"把想做的事，变成今天的一小步。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m017","text":"多问一个为什么，就多打开一扇门。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m033","text":"做错了可以改，你的价值不会因此变少。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m047","text":"问得具体一点，帮助就会更有用。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m073","text":"愿意再试一次，就还有新的可能。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m081","text":"试过以后总结方法，下一次就有经验可用。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m093","text":"相信自己可以进步，也接受自己需要帮助。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m108","text":"自己的第一种想法，值得认真验证。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m127","text":"熟悉的题，也可以尝试一种新解法。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m145","text":"听见一个新观点，先问它有什么依据。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m165","text":"一起解决问题时，每个人的认真都很重要。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m167","text":"诚实地记录错误，比漂亮地掩盖错误更有用。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m189","text":"先读完整题目，再急着动笔。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m204","text":"学习之外，你也值得拥有自己的兴趣。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m217","text":"把长题目画成线段图，关系也许更直观。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m240","text":"善意可以从今天的一句好好说话开始。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m246","text":"把两个旧想法连起来，也可能变成新办法。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m268","text":"愿意离开一点熟悉的地方，就会多一点经验。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m092","text":"不必和别人一样快，先走稳自己的节奏。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m296","text":"记录一次突破，困难时可以回来看看。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m015","text":"迈出小小一步，也值得为自己高兴。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m016","text":"答案很重要，想明白为什么更重要。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m040","text":"把同一个坑记下来，下次就更容易绕过去。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m057","text":"问清一个小地方，整道题可能就通了。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m062","text":"每天练一点，比偶尔着急练很多更容易坚持。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m080","text":"先做重要的一步，不必同时忙很多事。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m105","text":"自信可以来自一次次认真完成的小事。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m107","text":"看过讲解以后，合上答案再独立做一次。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m126","text":"把知识连起来，比把它们孤零零记住更有用。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m150","text":"保持好奇，让普通的一天也有新发现。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m159","text":"遇到分歧时，一起找证据比争输赢更有用。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m173","text":"借用别人的想法，记得说明从哪里学来。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m182","text":"开始前收好桌面，给注意力留出位置。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m199","text":"运动和玩耍，也是成长的一部分。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m219","text":"同一个结果，可以有不止一种计算方法。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m238","text":"不同的兴趣和长处，都值得被尊重。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m241","text":"新办法常常从一个“能不能这样”开始。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m258","text":"害怕也可以尝试，勇敢不是完全不紧张。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m273","text":"知道自己需要什么，是一项重要的本领。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m295","text":"今天帮助了一个人，也收获了一份成长。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m007","text":"先写下已知条件，思路就有了起点。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m028","text":"看起来相似的题，也要认真找不同。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m045","text":"今天改懂一道错题，就是一次实在的收获。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m056","text":"把疑问写下来，就不怕它悄悄溜走。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m070","text":"一次练习不决定全部，持续学习才会积累。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m076","text":"先弄清任务，再决定怎样用力。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m097","text":"会一道新题，就是给自己添了一份底气。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m116","text":"自己的草稿里，也可能藏着好主意。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m129","text":"能说出容易错的地方，也是掌握的一部分。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m144","text":"不熟悉的事物，也值得先了解再判断。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m155","text":"解释的时候举个例子，会更容易被理解。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m176","text":"认真完成小任务，是值得信任的开始。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m188","text":"习惯不靠一天完成，而靠一次次重复。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m201","text":"一天里既可以努力，也可以快乐地休息。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m225","text":"能把数学用起来，知识就有了新的生命力。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m239","text":"为别人高兴，不会让自己的光变少。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m247","text":"创造不一定很惊人，解决一个小麻烦也算。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m260","text":"这次的方法不合适，不代表所有方法都不行。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m278","text":"不必用别人的评价，写完自己的故事。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m289","text":"努力之后的小进步，也值得好好记住。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m008","text":"把“我想试试”变成“我试过了”。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m021","text":"会解释自己的想法，才是真的理解。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m039","text":"会检查的人，也在练习一种本领。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m059","text":"好奇心不需要标准答案的许可。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m067","text":"遇到难题时，先完成自己能做的部分。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m087","text":"草稿写得清楚，思路也更容易检查。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m277","text":"发现自己的进步，也认真看见自己的感受。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m114","text":"没有提示时想起来的办法，更能看出是否学会。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m125","text":"忘记一些很正常，及时回顾就能接回来。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m146","text":"看过以后想一想，知识才会变得有联系。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m154","text":"不同的想法，可以帮助大家看得更全面。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m174","text":"发现自己说错了，及时改正就很好。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m185","text":"每天固定一点学习时间，开始就不那么费劲。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m208","text":"认真吃饭、安心睡觉，都是今天的重要事情。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m216","text":"数字背后有数量，别只看符号不看意思。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m227","text":"别人的进步值得祝贺，自己的进步也值得。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m251","text":"把“如果”问下去，可能会看见新的可能。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m265","text":"失败的尝试，也能告诉你哪条路需要调整。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m276","text":"每天问问自己，今天真正弄懂了什么。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m300","text":"带着今天学会的一点点，轻松迎接新的一天。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m003","text":"先完成一小段，再挑战下一段。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m023","text":"不要只记住怎么做，还要知道为什么这样做。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m034","text":"先找到错在哪里，再想下一次怎么避免。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m053","text":"别人的办法可以参考，自己的理解需要建立。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m061","text":"进步有时很小，但小小的进步也算数。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m082","text":"做完不急着翻页，检查一下关键步骤。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m098","text":"不需要次次第一，也能成为认真的学习者。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m117","text":"把学过的方法用在新题上，是成长的证据。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m135","text":"旧知识用起来，才更容易成为自己的本领。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m148","text":"探索不一定很远，窗边也能找到好问题。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m162","text":"感谢别人的帮助，也记得付出自己的努力。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m172","text":"检查结果时，对自己认真，也对事实认真。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m190","text":"认真看清一个符号，可能就少走一段弯路。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m205","text":"放下难题散个步，有时会想到新办法。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m222","text":"看清大约有多少，精确计算就有了参照。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m232","text":"礼貌表达不同意见，也能坚持自己的想法。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m243","text":"先把点子画下来，再慢慢完善它。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m270","text":"挑战的目标可以是学会，而不只是赢。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m272","text":"发现哪里容易分心，就能想办法照顾注意力。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m291","text":"学习的快乐，可以从“我终于懂了”开始。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m011","text":"别急着完成全部，先做好眼前这一件。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m020","text":"思路卡住时，画一张图试试。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m035","text":"愿意订正，比假装全会更勇敢。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m055","text":"每个人都有不会的事，你可以放心发问。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m075","text":"坚持的样子，也可以从容而有节奏。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m078","text":"练习之后想一想，比只增加题量更有用。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m103","text":"别用“我就是不行”替自己关上门。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m106","text":"先自己想一会儿，再带着问题求助。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m122","text":"复习不是从头重来，是让理解更稳。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m143","text":"世界很大，今天可以先认识其中一个角落。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m156","text":"听到不同意见，先问问对方的理由。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m178","text":"需要帮助就说明，不必假装已经完成。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m191","text":"做事有准备，遇到变化就更从容。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m200","text":"照顾好身体，是认真学习的好伙伴。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m223","text":"把问题变简单一点，可能更容易发现关键。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m230","text":"不拿别人的错误开玩笑，是一种温柔的力量。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m249","text":"允许草稿不整齐，给想法留一点自由。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m259","text":"把难题分成小题，勇气就有了落脚点。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m271","text":"了解自己的节奏，才能安排合适的学习方法。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m287","text":"今天的一点明白，就是送给未来的一份礼物。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m004","text":"五分钟的尝试，也比一直犹豫更接近答案。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m025","text":"发现规律之后，再找个例子验证它。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m044","text":"错在哪里值得研究，不值得责怪自己。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m050","text":"提问之前先想一想，提问之后再试一试。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m072","text":"反复尝试时，也记得调整方法。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m086","text":"先估一估结果，答案就多了一道检查。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m095","text":"把注意力放在成长上，而不是只看一次分数。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m120","text":"独立完成一小题，也是一份扎实的成就。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m124","text":"重做一道旧错题，可以发现新的进步。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m142","text":"愿意探索的人，总能发现新的问题。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m158","text":"说“我有另一种想法”，可以温和也可以坚定。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m180","text":"负责不是永不出错，是愿意把问题处理好。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m183","text":"专注一小段，再让大脑休息一下。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m203","text":"做不出来的时候，先深呼吸，再看下一步。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m221","text":"数学里的检查，可以帮助直觉变得更可靠。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m235","text":"尊重别人的专注，也是在保护共同的学习空间。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m248","text":"别急着否定新点子，先看看能不能试一试。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m256","text":"难题可以有难度，你也可以有准备。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m274","text":"一次分数可以提供信息，不能说明你的全部。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m292","text":"完成一个小目标，就给自己一个真诚的肯定。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m013","text":"今天的努力，不需要等明天批准。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m026","text":"一个好问题，能带来比答案更远的探索。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m037","text":"算错一次，不代表你不会学数学。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m051","text":"一个看似简单的问题，也可能很有价值。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m068","text":"慢慢练熟的本领，往往更靠得住。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m083","text":"把容易混淆的地方放在一起比较。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m102","text":"发现自己的长处，也给不足留下成长的空间。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m118","text":"遇到不确定的答案，试着自己找证据。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m121","text":"今天学会的，过几天再见一次会更牢。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m140","text":"读书不必赶页数，理解一段也很有收获。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m151","text":"把自己的意思说清楚，也给别人说话的时间。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m171","text":"不知道答案时，可以坦然说“我还不确定”。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m192","text":"把学习用品放回原处，下一次开始会更轻松。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m209","text":"觉得压力太大时，寻求帮助很勇敢。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m215","text":"一个答案是否合理，可以先回到生活里想一想。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m234","text":"得到帮助时说谢谢，提供帮助时不取笑。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m253","text":"灵感来了先记住，完善可以慢慢来。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m267","text":"需要更多时间，不等于没有能力。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m284","text":"学会比较现在和过去的自己，发现真实的变化。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m297","text":"慢慢变好的过程，本身就值得珍惜。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m002","text":"不用等准备完美，先认真开始。","theme":"开始行动","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m019","text":"换一个角度，也许就看见了新办法。","theme":"学会思考","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m043","text":"勇敢面对不会的地方，学习才有真正的起点。","theme":"面对错误","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m052","text":"会求助的人，也在主动解决问题。","theme":"勇于提问","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m064","text":"给自己一点时间，本领需要慢慢长出来。","theme":"耐心坚持","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m077","text":"合适的方法，能让努力走得更顺。","theme":"方法与效率","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m100","text":"你已经学会过很多事，这次也可以继续探索。","theme":"自信成长","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m115","text":"别急着找参考答案，先给自己一次尝试。","theme":"独立尝试","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m128","text":"复习时先回想，再翻书确认。","theme":"复习巩固","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m147","text":"把一个新发现分享出去，快乐也会多一点。","theme":"阅读探索","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m161","text":"把任务分清楚，让每个人都有参与的机会。","theme":"表达合作","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m177","text":"做题时求真实，进步才看得清楚。","theme":"诚实负责","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m194","text":"一个好习惯，可以从今天的一次小选择开始。","theme":"专注习惯","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m198","text":"累了先喝口水、动一动，再回来试试。","theme":"生活与休息","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m213","text":"图形画准确一点，关系常常就清楚一点。","theme":"数学眼光","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m237","text":"说话之前想一想，怎样表达更清楚也更友善。","theme":"善意尊重","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m252","text":"画错的一条线，也许能变成另一幅图。","theme":"创造想象","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m261","text":"遇到困难时，先问“下一步能做什么”。","theme":"面对挑战","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m280","text":"看见自己的不足，是为了帮助自己成长。","theme":"自我认识","source":"原创成长寄语","kind":"modern-encouragement"},{"id":"m293","text":"看见自己越来越会做，是很踏实的快乐。","theme":"成长喜悦","source":"原创成长寄语","kind":"modern-encouragement"}].map(Object.freeze));
  const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'});
  const epoch=Date.UTC(2026,9,25),DAY=86400000;
  function key(date=new Date()){const parts=Object.fromEntries(formatter.formatToParts(date).map(p=>[p.type,p.value]));return `${parts.year}-${parts.month}-${parts.day}`;}
  function get(date=new Date(),profile='math'){const day=key(date),[year,month,dayOfMonth]=day.split('-').map(Number),delta=Math.floor((Date.UTC(year,month-1,dayOfMonth)-epoch)/DAY),offset=false?137:0,index=((delta+offset)%quotes.length+quotes.length)%quotes.length;return {...quotes[index],date:day,index};}
  const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function html(date=new Date(),profile='math'){const q=get(date,profile),[,month,day]=q.date.split('-');return `<figure class="daily-quote" id="daily-quote" data-quote-date="${q.date}" data-quote-id="${q.id}" aria-label="每日一句"><div class="daily-quote-top"><span class="daily-quote-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4L19 5"/></svg>每日一句 · ${esc(q.theme)}</span><time class="daily-quote-date" datetime="${q.date}">${Number(month)}月${Number(day)}日</time></div><blockquote>${esc(q.text)}</blockquote></figure>`;}
  let started=false;
  function watch(profile='math'){if(started||!root.document)return;started=true;const doc=root.document;function update(){if(doc.hidden)return;const el=doc.getElementById('daily-quote');if(el&&el.dataset.quoteDate!==key())el.outerHTML=html(new Date(),profile);}doc.addEventListener('visibilitychange',update);root.addEventListener('pageshow',update);root.addEventListener('focus',update);root.setInterval(update,60000);update();}
  return Object.freeze({quotes,get,key,html,watch});
});
